// In-memory store simulating a database.
// Replace with a real data source (e.g. Prisma/DB) in production.
let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function setNotificationPreference(value: boolean): Promise<void> {
  notificationsEnabled = value
}

"use server"

import { revalidatePath } from "next/cache"
import { getNotificationPreference, setNotificationPreference } from "./data"

export async function toggleNotifications() {
  const current = await getNotificationPreference()
  await setNotificationPreference(!current)

  // Refresh the current page's cached data so the updated preference
  // is shown without redirecting to another route.
  revalidatePath("/")
}

import { toggleNotifications } from "./actions"
import { getNotificationPreference } from "./data"

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "on" : "off"}.</p>
      <form action={toggleNotifications}>
        <button type="submit">Turn notifications {enabled ? "off" : "on"}</button>
      </form>
    </main>
  )
}
